traps.trap01.txt:
// 切换到map071朱仙镇

	If ($Event == 520) @Event520;
	
	Say("张琳心：还没拿到雪莲王呢！", 101);
	Return;
	
@Event520:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("情剑.mp3");
	LoadMap("map085_朱仙镇客栈.map");
	LoadNpc("map085.npc");
	LoadObj("map085.obj");
	SetPlayerPos(7, 17);
	SetPlayerDir(0);
	ShowSnow(0);
	FadeIn();
	
	Say("王佐：太好了，张姑娘及时赶回。岳元帅派出的人也已带回了药材。", 63);
	Say("客栈掌柜：现在两种药材都齐了，我可以开始熬制了。", 86);
	NpcGoto("王佐", 4, 25);
	FadeOut();
	Say("两个时辰以后……");
	SetNpcPos("王佐", 8, 18);
	SetNpcDir("王佐", 3);
	SetNpcPos("客栈掌柜", 7, 19);
	SetNpcDir("客栈掌柜", 4);
	FadeIn();
	Say("客栈掌柜：药已经熬好了，张姑娘快去给独孤少侠喝下。", 86);
	
	FadeOut();
	SetPlayerPos(8, 14);
	SetPlayerDir(3);
	SetNpcPos("客栈掌柜", 7, 17);
	SetNpcDir("客栈掌柜", 4);
	SetNpcActionFile("张琳心", 0, "mpc031_1.asf");
	SetNpcActionFile("张琳心", 1, "mpc031_1.asf");
	FadeIn();
	
	SetNpcActionFile("张琳心", 0, "mpc031_2.asf");   //喂药
	SetNpcActionFile("张琳心", 1, "mpc031_2.asf");
	NpcSpecialAction("张琳心", "mpc031_1.asf");
	Sleep(2000);
	Say("客栈掌柜：喝了这千年人参和雪莲王合制的奇药，再配合我这些日子的针灸疗法，独孤少侠应当会很快醒过来的。", 86);
	
	FadeOut();
	Say("过了一会，独孤剑终于醒了过来。");
	SetNpcActionFile("张琳心", 0, "mpc032.asf");	//坐在床边
	SetNpcActionFile("张琳心", 1, "mpc032.asf");
	NpcSpecialAction("张琳心", "mpc032.asf");
	FadeIn();
	
	SetNpcActionFile("独孤剑", 0, "mpc033_2.asf");	//独孤剑醒过来
	SetNpcActionFile("独孤剑", 1, "mpc033_2.asf");
	NpcSpecialAction("独孤剑", "mpc033_1.asf");
	Sleep(2000);
	
	Say("张琳心：独孤哥哥，你……你终于醒了！", 95);
	Say("独孤剑：我好象睡了好久……琳儿你怎么哭了？", 8);
	Say("张琳心：我……我还以为你活不过来了呢，老天有眼，谢天谢地，你终于醒过来了。", 26);
	Say("王佐：两位能够重新相聚，真是可喜可贺！古兄，我们还是先出去吧。", 63);
	Say("客栈掌柜：呵呵，王将军说的有理，我们两个还在这里碍手碍脚干什么？走，王将军，跟我去痛饮百杯，哈哈！", 86);
	NpcGotoEx("王佐", 4, 28);
	NpcGoto("客栈掌柜", 3, 27);
	DelNpc("王佐");
	SetNpcPos("客栈掌柜", 5, 37);
	SetNpcDir("客栈掌柜", 0);
	SaveNpc();
	Say("独孤剑：这是在哪里？", 8);
	Say("张琳心：这是朱仙镇的客栈，你在这里睡了快一个月了。", 21);
	Say("独孤剑：我睡了这么久？", 1);
	Say("独孤剑：琳儿……你瘦了……",1);
	Say("张琳心：……", 22);
	Say("张琳心：独孤哥哥……我真的好害怕……我好怕失去你，怕你再也醒不过来……", 26);
	Say("独孤剑：琳儿，我知道你一定为我受了很多苦。", 2);
	Say("张琳心：……", 26);
	Say("独孤剑：这些日子，我一直在做着一个梦，我梦见我娘……", 2);
	Say("张琳心：……你娘一定很美……", 95);
	Say("独孤剑：我从来没见过我娘。自从懂事起，我就一直跟在师傅身边……不过，我觉得，她长得，长得好像……琳儿你。", 2);
	Say("独孤剑：我就像回到了小时候，连路也走不稳……我娘，就一直扶着我，跟着我……", 2);
	Say("张琳心：独孤哥哥，只要你不嫌弃，琳儿愿意一辈子跟着你，陪着你……", 22);
	Say("独孤剑：琳儿……咳咳——", 2);
	Say("张琳心：独孤哥哥，快躺下，你伤还没有痊愈，好好休息吧！", 21);
	Say("独孤剑：琳儿，你别走。", 4);
	Say("张琳心：嗯，我就在这里陪着你，哪儿也不去。", 22);
	FadeOut();	
	
	Say("一夜过去——");
	SetNpcActionFile("张琳心", 0, "npc004_st.asf");	
	SetNpcActionFile("张琳心", 1, "npc004_pst.asf");
	SetPlayerPos(8, 18);
	SetPlayerDir(3);
	DelNpc("独孤剑");
	SaveNpc();
	PlayerChange(0);
	SetPlayerPos(7, 17);
	SetPlayerDir(7);
	SetNpcRelation("独孤剑", 0);
	SetNpcKind("独孤剑", 2); 
	AddNpc("npc004_张琳心.ini", 8, 18, 3);
	SetNpcKind("张琳心", 3);
	FullLife();
	FullThew();
	FullMana();
	SetPlayerScn();
	FadeIn();
	
	SetNpcKind("张琳心", 1);
	AddExp(18000);
	SetNpcKind("张琳心", 3);
	Say("张琳心：独孤哥哥，你感觉好些了么？", 21);
	Say("独孤剑：那药汤果然奇效，我现在不仅完全恢复，而且感觉神清气爽，好像功力不退反进了，只是在床上躺了这么久，实在气闷，不如你陪我出去走走吧？", 2);
	Say("张琳心：好。", 95);
	
 	DelGoods("Goods215_雪莲王.ini");
	SetNpcKind("张琳心", 3);
	SetNpcRelation("张琳心", 2);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	Assign($Event, 530);
	Say("您开始控制独孤剑。");
	Memo("张琳心回到朱仙镇客栈，岳元帅派去的人也采到了另一种药材，客栈掌柜将两种药材混在一起熬成了药汤。独孤剑喝完药后醒转过来，张琳心喜极而泣，两人执手相看泪眼，千言万语，尽在不言中。");
	Return;

